+const test = require('node:test');
+const assert = require('node:assert/strict');
+const { spawnSync } = require('node:child_process');
+const { join } = require('node:path');
+
+const command = join(__dirname, '..', 'bin', 'feecalc.js');
+
+function run(...args) {
+  return spawnSync(process.execPath, [command, ...args], { encoding: 'utf8' });
+}
+
+test('prints the requested fee and total in dollars', () => {
+  const result = run('200', '--days', '10');
+  assert.equal(result.status, 0);
+  assert.equal(result.stdout, 'Late fee: $5.00  Total due: $205.00\n');
+  assert.equal(result.stderr, '');
+});
+
+test('rounds the aggregate fee once, half cents up', () => {
+  const cases = [
+    [['1', '--days', '1'], 'Late fee: $0.00  Total due: $1.00\n'],
+    [['1', '--days', '2'], 'Late fee: $0.01  Total due: $1.01\n'],
+    [['1', '--days', '3'], 'Late fee: $0.01  Total due: $1.01\n'],
+    [['0', '--days', '0'], 'Late fee: $0.00  Total due: $0.00\n'],
+    [['0.01', '--days', '1'], 'Late fee: $0.00  Total due: $0.01\n'],
+  ];
+
+  for (const [args, expected] of cases) {
+    const result = run(...args);
+    assert.equal(result.status, 0, args.join(' '));
+    assert.equal(result.stdout, expected, args.join(' '));
+    assert.equal(result.stderr, '', args.join(' '));
+  }
+});
+
+test('accepts the approved design spellings and normalizes the output', () => {
+  const cases = [
+    [['0001.2', '--days', '02'], 'Late fee: $0.01  Total due: $1.21\n'],
+    [['.5', '--days', '+2'], 'Late fee: $0.00  Total due: $0.50\n'],
+    [['+2.', '--days', '2'], 'Late fee: $0.01  Total due: $2.01\n'],
+  ];
+
+  for (const [args, expected] of cases) {
+    const result = run(...args);
+    assert.equal(result.status, 0, args.join(' '));
+    assert.equal(result.stdout, expected, args.join(' '));
+    assert.equal(result.stderr, '', args.join(' '));
+  }
+});
+
+test('keeps cents exact beyond the safe integer range', () => {
+  const result = run('9007199254740993.00', '--days', '2');
+  assert.equal(result.status, 0);
+  assert.equal(result.stdout, 'Late fee: $45035996273704.97  Total due: $9052235251014697.97\n');
+  assert.equal(result.stderr, '');
+});
+
+test('rejects missing, malformed, duplicate, and extra arguments without stdout', () => {
+  const cases = [
+    [],
+    ['200'],
+    ['200', '--days'],
+    ['-1', '--days', '2'],
+    ['1.234', '--days', '2'],
+    ['1e2', '--days', '2'],
+    ['1', '--days', '-1'],
+    ['1', '--days', '1.5'],
+    ['1', '--days', '2', '--days', '3'],
+    ['1', '--days', '2', '--unknown'],
+    ['1', '--days', '2', '--cents'],
+  ];
+
+  for (const args of cases) {
+    const result = run(...args);
+    assert.notEqual(result.status, 0, args.join(' '));
+    assert.equal(result.stdout, '', args.join(' '));
+    assert.match(result.stderr, /^Error: .+\n$/, args.join(' '));
+  }
+});
